INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(66695, 'itIT', 'Sfida del destino: Sepolcro dei Primi', '', '', '', '', '', '', '', '', 45114),
(66694, 'itIT', 'Sfida del destino: Sanctum del Dominio', '', '', '', '', '', '', '', '', 45114),
(66661, 'itIT', 'È solo una moneta, quanto può costare?', 'Cerca un Alienatore a Oribos per avere delle informazioni.', '<Questo curioso oggetto fornisce più domande che risposte. come hai fatto ad averlo? A cosa serve? È pericoloso?>\n\n<Se la Città Eterna non ha risposte per te, sicuramente gli Alienatori che commerciano lì le avranno.>', '', '', '', '', '', '', 45114),
(66649, 'itIT', 'Far girare la ruota', 'Sconfiggi $1oa boss diversi nelle incursioni Predestinate.', '<Grazie alle numerose prove che hai affrontato senti il potere crescere dentro di te. Qualunque sia la fonte di queste anomalie, ti porta conforto invece di confusione.>\n\n< Approfondisci l\'incertezza, combatti contro l\'oscurità e afferra il destino con entrambe le mani.>', '', '', '', '', '', '', 45114),
(66648, 'itIT', 'Destino incrociato', 'Sconfiggi 30 boss diversi nelle incursioni Predestinate.', '<Ti gira la testa. I tuoi ricordi di questo luogo si oscurano e cambiano a ogni istante. Qualcosa è cambiato.>\n\n<Sei $gcerto:certa; che, nonostante la somiglianza, non è il posto che conoscevi. Non esattamente.>\n\n<Comunque, la strada che si dipana davanti a te ti chiama. Nessun inganno o distorsione possono ritardare il compiersi del tuo destino.>', '', '', '', '', '', '', 45114),
(66619, 'itIT', 'Antros', '', '', '', '', '', '', '', '', 45114),
(66618, 'itIT', 'Mor\'geth', '', '', '', '', '', '', '', '', 45114),
(65411, 'itIT', 'Situazione incomprensibile', '', '', '', '', '', '', '', '', 45114),
(54603, 'itIT', 'Sovrintendente Krix', '', '', '', '', '', '', '', '', 45114),
(54484, 'itIT', 'Modelli di Sartoria', '', '', '', '', '', '', '', '', 45114),
(54391, 'itIT', 'Donazioni per Rivafosca: Berillo Dorato Rapido', 'Raccogli $1oa Lonze Stagionate per Senedras al Porto di Boralus.', 'La giusta quantità di carne di qualità fornisce il nutrimento necessario ai nostri alleati prima della battaglia, senza contare che le truppe sono sempre contente di riscaldarsi con uno stufato per combattere i venti freddi e il gelo della notte.\n\nSe mi porti della Lonza Stagionata, la consegnerò ai nostri responsabili dei rifornimenti.', '', '', '', '', '', '', 45114),
(54388, 'itIT', 'Donazioni per Rivafosca: Casco da Immersione di Scaglialucida', 'Raccogli $1oa Incantamento Anello - Suggello del Colpo Critico per Mae Scuotibacchetta al Porto di Boralus.', '', '', '', '', '', '', '', 45114),
(54381, 'itIT', 'Donazioni per Rivafosca: Inchiostro Ultramarino', 'Raccogli $1oa Pescigatto Grigliati per Senedras al Porto di Boralus.', 'Salve, viandante.\n\nMi hanno chiesto di assicurarmi che le nostre riserve di cibo non scarseggino e ultimamente siamo a corto di pesce. Hai qualcosa da donare?', '', '', '', '', '', '', 45114),
(53317, 'itIT', 'Argento della Tempesta Denso', '', '', '', '', '', '', '', '', 45114),
(52438, 'itIT', 'Cavalcata folle', 'Unisciti alla battaglia al Fiume Lettocurvo.', 'Lascia che te lo dica, $gragazzo:ragazza;... questo credo sia il lavoro migliore che abbia mai fatto!\n\nOra che i miglioramenti sono stati implementati, non c\'è tempo da perdere.\n\nLa battaglia infuria al Fiume Lettocurvo; prendi lo Sparginferno e scatena la sua furia!', '', '', '', '', '', '', 45114),
(50823, 'itIT', 'Pronti a essere raccolti', 'Incontrati con Faucisaure e Sylvanas nell\'Avamposto di Zoram\'gar.', 'I Kaldorei hanno bloccato la nostra avanzata. In un mondo perfetto, avremmo marciato fino ad Auberdine e raggiunto Teldrassil prima che potessero rallentarci, ma tutto ciò ha poca importanza.\n\nMalfurion cercherà di bloccarci fino a quando la loro flotta non sarà tornata da Silitus. Fino ad allora, il suo esercito è troppo esiguo. Se solo riuscissimo a trovare un passaggio attraverso quei maledetti Fuochi Fatui.\n\nHo un\'idea... facciamo una chiacchierata con Faucisaure.', '', '', '', '', '', '', 45114),
(50772, 'itIT', 'A caccia', 'Trova la Capoguerra Sylvanas Ventolesto a Rivafosca.', 'Hai visto tutti quei Fuochi Fatui? Ho già visto una cosa simile, quando il demone Archimonde venne abbattuto da centinaia, anzi migliaia di quelle cose.\n\nTutto questo può significare soltanto una cosa: Malfurion ha richiesto supporto ai loro antenati.\n\nLa Capoguerra ha già inviato un gruppo d\'esplorazione verso Rivafosca per intercettarlo. Ti prego, $n: trova la Capoguerra e scopri se ha già catturato la sua preda.\n\nAbbiamo preso possesso di tutta Valtetra, ma dobbiamo continuare a tenere alta la pressione.', '', '', '', '', '', '', 45114),
(49053, 'itIT', 'Guardiano', '', '', '', '', '', '', '', '', 45114),
(47007, 'itIT', 'Beneficio della Torre della Magia', '', '', '', '', '', '', '', '', 45114),
(44940, 'itIT', 'Nell\'occhio della tempesta', 'Usa il Lancia Rampino dei Forgiatuono dalla cima della torre e raggiungi la fine del sentiero di montagna.', 'Eccoci qui. Mi sembra un buon posto per lanciarsi dall\'altro lato. Questo sentiero dovrebbe portarti fino in cima.\n\nIn base alle mie informazioni, i tuoi draghi dovrebbero essere là sopra. Speriamo solo che siano ancora in grado di aiutarti.', '', '', '', '', '', '', 45114),
(44922, 'itIT', 'Nell\'occhio della tempesta', 'Usa il Lancia Rampino dei Forgiatuono dalla cima della torre e raggiungi la fine del sentiero di montagna.', 'Eccoci qui. Mi sembra un buon posto per lanciarsi dall\'altro lato. Questo sentiero dovrebbe portarti fino in cima.\n\nIn base alle mie informazioni, i tuoi draghi dovrebbero essere là sopra. Speriamo solo che siano ancora in grado di aiutarti.', '', '', '', '', '', '', 45114),
(41695, 'itIT', 'PERICOLO: Defilia', '', '', '', '', '', '', '', '', 45114),
(31528, 'itIT', 'Una degna sfida: Maestro Oscuro Gandling', 'Completa Scholomance in modalità Sfida.', '$n, ho bisogno di allestire un gruppo senza paura da inviare nelle profondità di Scholomance. Attivate il Globo dello Sfidante che trovate all\'interno e purificate Scholomance dalla presenza maligna del Maestro Oscuro Gandling.$B$BTornate da me quando avrete portato a termine questa sfida e vi ricompenserò adeguatamente.', '', '', '', '', '', '', 45114),
(8421, 'itIT', 'The Wrong Stuff', 'Bring 10 Rotting Wood and 4 Bloodvenom Essence to Impsy in Felwood.', 'Now that I have my felcloth, I can really begin making *my* pet.$b$bIt\'s going to need some eyes though.  Perhaps you could rip some rotting wood from the irontree folk for me, so I can carve out some lovely eyes.  They\'re up north in the Irontree Woods.$b$bI\'ll also need some bloodvenom essence to give it that new demon smell.  The tainted oozes carry the essence, and they hang out right here near Niby and me.', '', '', '', '', '', '', 45114),
(7602, 'itIT', 'Flawless Fel Essence', 'Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.$B$BThe Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.$B$BRecover the Flawless Fel Essences and return  to Impsy in Felwood.', 'If you\'re going to reanimate Kroshius, you\'re going to need Fel fire. I can make Fel fire but it\'s going to require some components.$B$BYou need to bring me flawless Fel essences from three distinct regions of the world.$B$BThe Legashi Satyrs of Azshara will have the first essence type; the Jaedenar legionnaires of Jaedenar the second type and the felguard sentries of the Blasted Lands the third.$B$BBring me back one of each essence type and I will create the Fel fire, allowing you to reanimate Kroshius.', '', '', '', '', '', '', 45114);

